-- โรงอาหารหอชาย: the three stalls and their menus, transcribed from ร้านหอชาย.pdf (27 ก.ย. 69).
-- Store photos are the menu-board photos in that PDF (frontend/static/stores/male-dorm-NN.webp); dishes have none yet.
-- Dishes the PDF lists together at one price ("ข้าวไก่ทอด / ข้าวไก่ย่าง 40") are separate items.
-- Stores start hidden and closed; the team shows them from the console. Safe to run twice: existing rows are kept.
begin;
select public.log_admin('STORE_CREATED', 'store', 'male-dorm-01', 'ส้มตำ @หอชาย', '{"source": "ร้านหอชาย.pdf"}'::jsonb) where not exists (select 1 from public.admin_log where action = 'STORE_CREATED' and target_id = 'male-dorm-01');
select public.log_admin('STORE_CREATED', 'store', 'male-dorm-02', 'อาหารพม่า (Burmese Food)', '{"source": "ร้านหอชาย.pdf"}'::jsonb) where not exists (select 1 from public.admin_log where action = 'STORE_CREATED' and target_id = 'male-dorm-02');
select public.log_admin('STORE_CREATED', 'store', 'male-dorm-03', 'สเต็กหอชาย by นิวบอร์น', '{"source": "ร้านหอชาย.pdf"}'::jsonb) where not exists (select 1 from public.admin_log where action = 'STORE_CREATED' and target_id = 'male-dorm-03');
commit;
